### 1. Complexity Scoring & Logic Utilities (`src/logic/initiation.ts`)

This module contains the "brains" of the initiation phase, calculating the weighted complexity score and budget ranges based on discovery inputs.

```typescript
import { ProjectComplexity, OptimizationStrategy } from "../types";

export interface DiscoveryMetrics {
  technicalNovelty: 1 | 2 | 3; // 1: Standard, 2: Complex, 3: Research-heavy
  integrationCount: number;
  stakeholderCount: number;
  timelineUrgency: 1 | 2 | 3; // 1: Flexible, 2: Standard, 3: Aggressive
  isRegulated: boolean;
}

/**
 * Calculates a weighted complexity score from 1 to 10.
 * Weights: Tech(30%), Integrations(20%), Stakeholders(10%), Urgency(20%), Compliance(20%)
 */
export function calculateComplexityScore(metrics: DiscoveryMetrics): ProjectComplexity {
  const score = 
    (metrics.technicalNovelty * 1.0) + 
    (Math.min(metrics.integrationCount, 5) * 0.4) + 
    (Math.min(metrics.stakeholderCount, 10) * 0.1) + 
    (metrics.timelineUrgency * 0.6) + 
    (metrics.isRegulated ? 2 : 0);

  return Math.min(Math.max(Math.round(score), 1), 10) as ProjectComplexity;
}

/**
 * Generates an initial budget range based on complexity and strategy.
 * This is a baseline estimate for the "Discovery Pattern".
 */
export function estimateInitialBudget(complexity: number, strategy: OptimizationStrategy) {
  const baseRate = 50000; // Base unit cost
  const multiplier = complexity * 1.5;

  let strategyAdjustment = 1.0;
  if (strategy === 'time') strategyAdjustment = 1.3; // Speed costs more
  if (strategy === 'budget') strategyAdjustment = 0.8; // Efficiency focus

  const midPoint = baseRate * multiplier * strategyAdjustment;

  return {
    min: Math.round(midPoint * 0.8),
    max: Math.round(midPoint * 1.2)
  };
}
```

