import { z } from "zod";
import { mcp } from "../index";
import { supabase } from "../lib/supabase";
import { calculateComplexityScore, estimateInitialBudget, DiscoveryMetrics } from "../logic/initiation";
import { v4 as uuidv4 } from "uuid";

/**
 * @mcp.tool("create_project")
 * Functional tool to initialize a project structure in the database.
 */
mcp.tool("create_project", {
  name: "The official project name",
  description: "A detailed description of the project goals",
  strategy: z.enum(["time", "budget", "balanced"]).default("balanced"),
  metrics: z.object({
    technicalNovelty: z.number().min(1).max(3),
    integrationCount: z.number(),
    stakeholderCount: z.number(),
    timelineUrgency: z.number().min(1).max(3),
    isRegulated: z.boolean()
  }),
  owner_id: z.string().uuid().optional() // Provided by the auth context in Next.js
}, async (input) => {
  try {
    const projectId = uuidv4();

    // 1. Run Complexity Scoring Logic
    const complexityScore = calculateComplexityScore(input.metrics as DiscoveryMetrics);

    // 2. Calculate Initial Budget Ranges
    const budget = estimateInitialBudget(complexityScore, input.strategy);

    // 3. Persist to Supabase
    const { data, error } = await supabase
      .from('projects')
      .insert({
        id: projectId,
        name: input.name,
        description: input.description,
        status: 'discovery',
        complexity_score: complexityScore,
        strategy: input.strategy,
        budget_min: budget.min,
        budget_max: budget.max,
        confidence_interval: 0.70, // Start with 70% confidence during discovery
        metadata: {
          discovery_metrics: input.metrics,
          initialized_at: new Date().toISOString()
        }
      })
      .select()
      .single();

    if (error) throw error;

    // 4. Return Structured Output for the LLM
    return {
      content: [
        {
          type: "text",
          text: `Project "${input.name}" initialized successfully.`
        },
        {
          type: "json",
          data: {
            project_id: projectId,
            complexity_score: complexityScore,
            estimated_budget_range: `${budget.min.toLocaleString()} - ${budget.max.toLocaleString()} USD`,
            status: "discovery",
            next_recommended_step: "/milestone-planning"
          }
        }
      ]
    };
  } catch (err: any) {
    return {
      isError: true,
      content: [{ type: "text", text: `Failed to create project: ${err.message}` }]
    };
  }
});
