As the **Specialized Worker in Algorithmic Development and Project Management Theory**, I have designed and implemented the **Milestone Planning and Timeline Generation** engine. 

This phase transitions the project from a high-level "Discovery" state into a mathematically modeled execution roadmap. The core of this implementation is a **Critical Path Method (CPM)** algorithm, which identifies the longest sequence of dependent tasks and determines the project's earliest possible completion date, accounting for a **15% Buffer Capacity** to manage risk.

---

### 1. The Critical Path Method (CPM) Engine (`src/logic/timelineEngine.ts`)

This module implements the deterministic logic for scheduling. It performs a Forward Pass (to find Early Start/Finish), a Backward Pass (to find Late Start/Finish), and identifies the "Slack" or "Float" for each milestone.

```typescript
import { Milestone, Dependency, TimelineResult } from "../types";

/**
 * Core Algorithmic Implementation of Critical Path Method (CPM)
 */
export class CPMEngine {
  /**
   * Calculates the timeline, identifies the critical path, and applies a 15% buffer.
   */
  public static calculate(milestones: Milestone[]): TimelineResult {
    const milestoneMap = new Map<string, Milestone>(milestones.map(m => [m.id, { ...m }]));
    const sortedIds = this.topologicalSort(milestones);

    // 1. Forward Pass: Calculate Early Start (ES) and Early Finish (EF)
    sortedIds.forEach(id => {
      const milestone = milestoneMap.get(id)!;
      const predecessors = milestones.filter(m => m.dependencies?.includes(id)); // Note: logic depends on how dependencies are stored

      // In our schema, milestone.dependencies = IDs of tasks that MUST FINISH before this starts.
      const depIds = milestone.dependencies || [];
      if (depIds.length === 0) {
        milestone.es = 0;
      } else {
        milestone.es = Math.max(...depIds.map(dId => milestoneMap.get(dId)!.ef || 0));
      }
      milestone.ef = milestone.es + milestone.duration_days;
    });

    // 2. Backward Pass: Calculate Late Finish (LF) and Late Start (LS)
    const projectDuration = Math.max(...Array.from(milestoneMap.values()).map(m => m.ef || 0));
    [...sortedIds].reverse().forEach(id => {
      const milestone = milestoneMap.get(id)!;
      const successors = Array.from(milestoneMap.values()).filter(m => m.dependencies?.includes(id));

      if (successors.length === 0) {
        milestone.lf = projectDuration;
      } else {
        milestone.lf = Math.min(...successors.map(s => s.ls || projectDuration));
      }
      milestone.ls = milestone.lf - milestone.duration_days;
      milestone.slack = milestone.ls - milestone.es;
    });

    // 3. Identify Critical Path & Buffer
    const criticalPath = Array.from(milestoneMap.values())
      .filter(m => (m.slack || 0) <= 0)
      .map(m => m.id);

    const bufferDays = Math.ceil(projectDuration * 0.15);
    const totalDurationWithBuffer = projectDuration + bufferDays;

    return {
      milestones: Array.from(milestoneMap.values()),
      criticalPath,
      projectDurationDays: projectDuration,
      bufferDays,
      totalDurationWithBuffer,
      generatedAt: new Date().toISOString()
    };
  }

  /**
   * Ensures milestones are processed in dependency order.
   */
  private static topologicalSort(milestones: Milestone[]): string[] {
    const nodes = new Set(milestones.map(m => m.id));
    const sorted: string[] = [];
    const visited = new Set<string>();
    const visiting = new Set<string>();

    const visit = (id: string) => {
      if (visiting.has(id)) throw new Error("Circular dependency detected in milestone planning.");
      if (!visited.has(id)) {
        visiting.add(id);
        const m = milestones.find(milestone => milestone.id === id);
        (m?.dependencies || []).forEach(depId => visit(depId));
        visiting.delete(id);
        visited.add(id);
        sorted.push(id);
      }
    };

    nodes.forEach(id => visit(id));
    return sorted;
  }
}
```

