### 3. The Generate Timeline Tool (`src/tools/generateTimeline.ts`)

This tool executes the CPM algorithm and persists the resulting roadmap to Supabase.

```typescript
import { z } from "zod";
import { mcp } from "../index";
import { supabase } from "../lib/supabase";
import { CPMEngine } from "../logic/timelineEngine";
import { v4 as uuidv4 } from "uuid";

/**
 * @mcp.tool("generate_timeline")
 * Persists milestones and calculates the project roadmap using CPM.
 */
mcp.tool("generate_timeline", {
  project_id: z.string().uuid(),
  milestones: z.array(z.object({
    name: z.string(),
    description: z.string(),
    duration_days: z.number().positive(),
    dependencies: z.array(z.string()).optional(), // Array of milestone names or temp IDs
  }))
}, async (input) => {
  try {
    // 1. Assign local IDs for the CPM algorithm
    const milestonesWithIds = input.milestones.map(m => ({
      ...m,
      id: uuidv4(),
      project_id: input.project_id,
      status: 'planned'
    }));

    // Map names to IDs to resolve dependencies provided as strings
    const nameToIdMap = new Map(milestonesWithIds.map(m => [m.name, m.id]));
    const processedMilestones = milestonesWithIds.map(m => ({
      ...m,
      dependencies: (m.dependencies || []).map(depName => nameToIdMap.get(depName) || depName)
    }));

    // 2. Execute CPM Algorithm
    const timeline = CPMEngine.calculate(processedMilestones as any);

    // 3. Persist Milestones to Supabase
    const { error: mError } = await supabase
      .from('milestones')
      .insert(timeline.milestones.map(m => ({
        id: m.id,
        project_id: m.project_id,
        name: m.name,
        description: m.description,
        duration_days: m.duration_days,
        dependencies: m.dependencies,
        early_start: m.es,
        early_finish: m.ef,
        late_start: m.ls,
        late_finish: m.lf,
        slack: m.slack,
        is_critical_path: timeline.criticalPath.includes(m.id)
      })));

    if (mError) throw mError;

    // 4. Update Project with Timeline Metadata
    const { error: pError } = await supabase
      .from('projects')
      .update({
        status: 'planning',
        total_duration_days: timeline.totalDurationWithBuffer,
        buffer_days: timeline.bufferDays,
        critical_path_data: timeline.criticalPath,
        updated_at: new Date().toISOString()
      })
      .eq('id', input.project_id);

    if (pError) throw pError;

    return {
      content: [
        {
          type: "text",
          text: `Timeline generated for Project ${input.project_id}.`
        },
        {
          type: "json",
          data: {
            total_duration_inc_buffer: `${timeline.totalDurationWithBuffer} days`,
            risk_buffer_added: `${timeline.bufferDays} days (15%)`,
            critical_path_milestones: timeline.milestones
              .filter(m => timeline.criticalPath.includes(m.id))
              .map(m => m.name),
            next_recommended_step: "/resource-optimization"
          }
        }
      ]
    };
  } catch (err: any) {
    return {
      isError: true,
      content: [{ type: "text", text: `Timeline Generation Failed: ${err.message}` }]
    };
  }
});
```

