### 1. The Optimization Engine (`src/logic/resourceEngine.ts`)

This core logic handles the heavy lifting of matching tasks to the right people while monitoring team health.

```typescript
import { Resource, Task, AssignmentResult, OptimizationStrategy } from "../types";

/**
 * ResourceOptimizationEngine
 * Implements set-based skill matching and multi-constraint allocation logic.
 */
export class ResourceOptimizationEngine {

  /**
   * Main entry point for resource allocation logic.
   */
  public static optimize(
    tasks: Task[],
    resources: Resource[],
    strategy: OptimizationStrategy
  ): AssignmentResult {
    const assignments: any[] = [];
    const resourceLoadMap = new Map<string, number>(resources.map(r => [r.id, 0]));

    // Sort tasks by priority or duration to ensure critical items are staffed first
    const sortedTasks = [...tasks].sort((a, b) => b.priority - a.priority);

    for (const task of sortedTasks) {
      const candidates = resources.map(resource => {
        const skillScore = this.calculateSkillMatch(task.required_skills, resource.skills);
        const availabilityScore = this.calculateAvailabilityScore(resource, resourceLoadMap.get(resource.id) || 0, task.estimated_hours);
        const costScore = this.calculateCostScore(resource, resources);

        // Weighted scoring based on strategy
        const totalScore = this.applyStrategyWeights(strategy, skillScore, availabilityScore, costScore);

        return { resource, totalScore, skillScore };
      });

      // Filter candidates who meet a minimum skill threshold (e.g., 40% match)
      const viableCandidates = candidates
        .filter(c => c.skillScore >= 0.4)
        .sort((a, b) => b.totalScore - a.totalScore);

      if (viableCandidates.length > 0) {
        const bestMatch = viableCandidates[0].resource;
        assignments.push({
          task_id: task.id,
          resource_id: bestMatch.id,
          match_score: viableCandidates[0].skillScore,
          utilization_after_assignment: ((resourceLoadMap.get(bestMatch.id)! + task.estimated_hours) / bestMatch.capacity_hours) * 100
        });

        // Update local load tracking
        resourceLoadMap.set(bestMatch.id, (resourceLoadMap.get(bestMatch.id) || 0) + task.estimated_hours);
      }
    }

    return {
      assignments,
      resourceMetrics: this.calculateTeamMetrics(resources, resourceLoadMap),
      strategyUsed: strategy,
      timestamp: new Date().toISOString()
    };
  }

  /**
   * Set-based comparison for skill matching.
   */
  private static calculateSkillMatch(required: string[], possessed: string[]): number {
    if (required.length === 0) return 1.0;
    const intersection = required.filter(skill => possessed.includes(skill));
    return intersection.length / required.length;
  }

  /**
   * Calculates availability score (inverse of current load).
   */
  private static calculateAvailabilityScore(resource: Resource, currentLoad: number, taskHours: number): number {
    const remaining = resource.capacity_hours - currentLoad;
    if (remaining <= 0) return 0;
    return Math.min(remaining / taskHours, 1.0);
  }

  /**
   * Normalizes cost score (lower cost = higher score).
   */
  private static calculateCostScore(resource: Resource, allResources: Resource[]): number {
    const rates = allResources.map(r => r.hourly_rate);
    const minRate = Math.min(...rates);
    const maxRate = Math.max(...rates);
    if (maxRate === minRate) return 1.0;
    return 1 - ((resource.hourly_rate - minRate) / (maxRate - minRate));
  }

  /**
   * Applies strategy-specific weights to the scoring components.
   */
  private static applyStrategyWeights(
    strategy: OptimizationStrategy,
    skill: number,
    availability: number,
    cost: number
  ): number {
    switch (strategy) {
      case 'TIME':
        // Prioritize skill and availability to finish fast
        return (skill * 0.6) + (availability * 0.4) + (cost * 0.0);
      case 'BUDGET':
        // Prioritize lower cost resources
        return (skill * 0.3) + (availability * 0.1) + (cost * 0.6);
      case 'BALANCED':
      default:
        // Even distribution
        return (skill * 0.4) + (availability * 0.4) + (cost * 0.2);
    }
  }

  /**
   * Generates burnout risk and efficiency metrics.
   */
  private static calculateTeamMetrics(resources: Resource[], loadMap: Map<string, number>) {
    return resources.map(r => {
      const load = loadMap.get(r.id) || 0;
      const utilization = (load / r.capacity_hours);
      return {
        resource_id: r.id,
        name: r.name,
        utilization: utilization * 100,
        burnout_risk: utilization > 1.0 ? 'CRITICAL' : utilization > 0.8 ? 'HIGH' : 'STABLE',
        efficiency_score: utilization > 0 ? (1 / utilization) : 0 // Simplified efficiency proxy
      };
    });
  }
}
