### 2. The `track_progress` Tool (`src/tools/trackProgress.ts`)

This tool performs the heavy lifting for predictive analytics, querying Supabase for historical milestone performance.

```typescript
import { z } from "zod";
import { mcp } from "../index";
import { supabase } from "../lib/supabase";
import { addDays, format, differenceInDays } from "date-fns";

mcp.tool("track_progress", {
  project_id: z.string().uuid(),
  include_predictions: z.boolean().default(true)
}, async ({ project_id, include_predictions }) => {
  try {
    // 1. Fetch Project and Milestone Data
    const { data: project } = await supabase.from('projects').select('*').eq('id', project_id).single();
    const { data: milestones } = await supabase.from('milestones').select('*').eq('project_id', project_id);

    if (!milestones) throw new Error("No milestones found");

    const now = new Date();
    const completed = milestones.filter(m => m.status === 'completed');
    const pending = milestones.filter(m => m.status !== 'completed');

    // 2. Calculate Basic Metrics
    const totalPlannedDays = milestones.reduce((sum, m) => sum + m.duration_days, 0);
    const earnedValue = completed.reduce((sum, m) => sum + m.duration_days, 0);
    const progressPercent = (earnedValue / totalPlannedDays) * 100;

    // 3. Predictive Analytics Logic
    let predictions = {};
    if (include_predictions && completed.length > 0) {
      // Calculate Velocity: Actual Days Taken / Planned Days
      const velocities = completed.map(m => {
        const actual = differenceInDays(new Date(m.actual_finish), new Date(m.actual_start));
        return actual / m.duration_days;
      });

      const avgVelocity = velocities.reduce((a, b) => a + b, 0) / velocities.length;
      const remainingPlannedDays = pending.reduce((sum, m) => sum + m.duration_days, 0);

      // Calculate Variance for Confidence Intervals
      const variance = velocities.reduce((a, b) => a + Math.pow(b - avgVelocity, 2), 0) / velocities.length;
      const stdDev = Math.sqrt(variance);

      const daysToFinish = remainingPlannedDays * avgVelocity;
      const marginOfError = 1.96 * stdDev * Math.sqrt(pending.length);

      predictions = {
        estimated_completion_date: format(addDays(now, daysToFinish), 'yyyy-MM-dd'),
        confidence_interval_95: {
          optimistic: format(addDays(now, daysToFinish - marginOfError), 'yyyy-MM-dd'),
          pessimistic: format(addDays(now, daysToFinish + marginOfError), 'yyyy-MM-dd')
        },
        current_velocity_multiplier: avgVelocity.toFixed(2), // > 1 means slower than planned
        schedule_performance_index: (1 / avgVelocity).toFixed(2)
      };
    }

    return {
      content: [{
        type: "json",
        data: {
          project_name: project.name,
          overall_progress: `${progressPercent.toFixed(1)}%`,
          milestone_stats: {
            total: milestones.length,
            completed: completed.length,
            pending: pending.length
          },
          health_metrics: predictions,
          status: progressPercent >= 100 ? 'delivered' : 'active'
        }
      }]
    };
  } catch (err: any) {
    return { isError: true, content: [{ type: "text", text: err.message }] };
  }
});
```

