import { z } from "zod";
import { mcp } from "../index";
import { supabase } from "../lib/supabase";

mcp.tool("identify_blockers", {
  project_id: z.string().uuid()
}, async ({ project_id }) => {
  // 1. Fetch active blockers and milestone context
  const { data: blockers } = await supabase
    .from('blockers')
    .select('*, milestones(*)')
    .eq('project_id', project_id)
    .eq('status', 'active');

  const { data: overdueMilestones } = await supabase
    .from('milestones')
    .select('*')
    .eq('project_id', project_id)
    .lt('late_finish_date', new Date().toISOString())
    .neq('status', 'completed');

  const formattedBlockers = (blockers || []).map(b => {
    const isCritical = b.milestones.is_critical_path;
    const slack = b.milestones.slack;

    let severity = "LOW";
    if (isCritical) severity = "HIGH";
    else if (slack < 3) severity = "MEDIUM";

    return {
      id: b.id,
      issue: b.description,
      milestone: b.milestones.name,
      severity,
      impact: isCritical ? "Directly delaying project completion date." : `Consuming ${slack} days of float.`,
      resolution_strategy: b.suggested_fix || "Requires immediate PM intervention."
    };
  });

  // 2. Add automated detection for overdue items without explicit blocker entries
  const overdueAlerts = (overdueMilestones || []).map(m => ({
    issue: `Milestone Overdue: ${m.name}`,
    severity: m.is_critical_path ? "HIGH" : "MEDIUM",
    impact: "Missed Late Finish boundary. Buffers are being consumed.",
    resolution_strategy: "Re-run /resource-optimization to recover time."
  }));

  return {
    content: [{
      type: "json",
      data: {
        active_blockers: [...formattedBlockers, ...overdueAlerts],
        summary: {
          high_severity_count: [...formattedBlockers, ...overdueAlerts].filter(x => x.severity === "HIGH").length,
          total_blockers: formattedBlockers.length + overdueAlerts.length
        }
      }
    }]
  };
});
