### 1. Risk Matrix & Governance Logic (`src/logic/riskManagement.ts`)

This module defines the mathematical framework for the Probability vs. Impact matrix and the automated severity classification.

```typescript
import { RiskSeverity, RiskCategory } from "../types";

export interface RiskInput {
  probability: number; // 1-5
  impact: number;      // 1-5
}

/**
 * Calculates the Risk Score and assigns a Severity Level.
 * Score = Probability * Impact (Max 25)
 */
export function analyzeRisk(input: RiskInput): { score: number; severity: RiskSeverity } {
  const score = input.probability * input.impact;

  let severity: RiskSeverity = 'low';
  if (score >= 15) severity = 'critical';
  else if (score >= 10) severity = 'high';
  else if (score >= 5) severity = 'medium';

  return { score, severity };
}

/**
 * Generates automated mitigation strategy templates based on category and severity.
 */
export function getMitigationGuidance(category: RiskCategory, severity: RiskSeverity): string {
  const strategies: Record<RiskCategory, string> = {
    technical: "Implement architectural spikes, increase unit test coverage, or conduct external security audits.",
    resource: "Trigger /resource-optimization to identify backup personnel or adjust capacity leveling.",
    schedule: "Analyze the Critical Path for parallel opportunities or apply 15% buffer capacity.",
    budget: "Review cost-per-day of high-utilization assets and adjust focus to 'Budget-Focused' strategy.",
    compliance: "Consult legal/governance leads and initiate a mandatory security review gate."
  };

  return severity === 'critical' 
    ? `IMMEDIATE ACTION REQUIRED: ${strategies[category]}` 
    : `Recommended Mitigation: ${strategies[category]}`;
}
