### 2. Real-time Synchronization Hook

To ensure the dashboard reflects the "Agentic Workflows" as they happen, we implement a Supabase Realtime hook.

```typescript
// src/hooks/useProjectRealtime.ts
import { useEffect, useState } from 'react';
import { supabase } from '@/lib/supabase';

export function useProjectRealtime(projectId: string) {
  const [data, setData] = useState<any>(null);

  useEffect(() => {
    // 1. Initial Fetch
    const fetchProjectState = async () => {
      const { data: state } = await supabase
        .from('projects')
        .select('*, milestones(*), project_risks(*), blockers(*)')
        .eq('id', projectId)
        .single();
      setData(state);
    };

    fetchProjectState();

    // 2. Realtime Subscription
    const channel = supabase
      .channel(`project-updates-${projectId}`)
      .on('postgres_changes', { 
        event: '*', 
        schema: 'public', 
        table: 'milestones',
        filter: `project_id=eq.${projectId}` 
      }, fetchProjectState)
      .on('postgres_changes', { 
        event: '*', 
        schema: 'public', 
        table: 'blockers',
        filter: `project_id=eq.${projectId}` 
      }, fetchProjectState)
      .subscribe();

    return () => { supabase.removeChannel(channel); };
  }, [projectId]);

  return data;
}
```

