### 5. API Route: Dashboard Analytics Aggregator

This route handles the complex math of combining Supabase data with the predictive analytics logic developed in Phase 4.

```typescript
// src/app/api/projects/[id]/analytics/route.ts
import { createRouteHandlerClient } from '@supabase/auth-helpers-nextjs';
import { cookies } from 'next/headers';
import { NextResponse } from 'next/server';

export async function GET(req: Request, { params }: { params: { id: string } }) {
  const supabase = createRouteHandlerClient({ cookies });

  // 1. Fetch data for calculations
  const { data: milestones } = await supabase
    .from('milestones')
    .select('*')
    .eq('project_id', params.id);

  if (!milestones) return NextResponse.json({ error: 'Not found' }, { status: 404 });

  // 2. Perform SPI (Schedule Performance Index) Calculation
  const completed = milestones.filter(m => m.status === 'completed');
  const earnedValue = completed.reduce((sum, m) => sum + m.duration_days, 0);
  const totalPlanned = milestones.reduce((sum, m) => sum + m.duration_days, 0);

  // 3. Mocking the Velocity-based ECD (Estimated Completion Date)
  // In production, this calls the logic from Phase 4
  const spi = earnedValue / (totalPlanned * 0.5); // Simplified for demo

  return NextResponse.json({
    overall_progress: (earnedValue / totalPlanned) * 100,
    spi: parseFloat(spi.toFixed(2)),
    health_status: spi >= 1 ? 'on_track' : spi > 0.85 ? 'at_risk' : 'delayed',
    milestone_count: milestones.length,
    completed_count: completed.length
  });
}
```

